section.programlisting:

List<GlossaryEntry> glossary = List.of(
    new GlossaryEntry("LIB-1", "Apache OpenNLP"),
    new GlossaryEntry("ALG-42", "maximum entropy model"),
    new GlossaryEntry("ALG-7", "perceptron model"));

DocumentAnalyzer analyzer = DocumentAnalyzer.builder()
    .add(new TokenizerAnnotator(WhitespaceTokenizer.INSTANCE))
    .add(new GlossaryAnnotator(new AhoCorasickGlossaryMatcher(glossary, true)))
    .build();

Document document = analyzer.analyze(
    "Apache OpenNLP ships a Maximum Entropy model and a perceptron model.");

List<Annotation<GlossaryMatch>> hits = document.get(GlossaryAnnotator.GLOSSARY);
// three hits: "Apache OpenNLP", "Maximum Entropy model", "perceptron model"


AhoCorasickGlossaryMatcher matcher = new AhoCorasickGlossaryMatcher(
    List.of(new GlossaryEntry("ST", "strasse")),
    true,
    GermanUmlautCharSequenceNormalizer.getInstance());

List<GlossaryMatch> hits = matcher.match("Die Straße ist frei.");
// one hit whose span covers the original "Straße"


TermAnalyzer terms = TermAnalyzer.builder()
    .caseFold()
    .stem(new SnowballStemmerFactory(SnowballStemmer.ALGORITHM.ENGLISH))
    .build();

TermAnalyzingGlossaryMatcher matcher = new TermAnalyzingGlossaryMatcher(
    List.of(new GlossaryEntry("FOOD", "hot dog")), terms);

List<GlossaryMatch> hits = matcher.match("the hot dogs were cold");
// one hit whose span covers the original "hot dogs"


OffsetAwareNormalizer contractions = TextNormalizer.builder()
    .with(EnglishContractionCharSequenceNormalizer.getInstance())
    .buildAligned();

TermAnalyzingGlossaryMatcher expanded = new TermAnalyzingGlossaryMatcher(
    List.of(new GlossaryEntry("SHIPPING", "can not ship order")), terms, contractions);

List<GlossaryMatch> expandedHits = expanded.match("We 'can't ship orders' today.");
// SHIPPING at [4..21), covering "can't ship orders"


TermAnalyzer analyzer = TermAnalyzer.builder()
    .caseFold()
    .stem(new SnowballStemmerFactory(SnowballStemmer.ALGORITHM.ENGLISH))
    .build();

List<GlossaryEntry> glossary = List.of(
    new GlossaryEntry("NYC", "New York City"),
    new GlossaryEntry("FOOD", "hot dog"));

GlossaryMatcher exact = new AhoCorasickGlossaryMatcher(glossary, true);
GlossaryMatcher inflected = new TermAnalyzingGlossaryMatcher(glossary, analyzer);
GlossaryMatcher composite = new CompositeGlossaryMatcher(List.of(exact, inflected));

List<GlossaryMatch> matches = composite.match("Hot dogs are sold across New York City.");
// two hits in text order: FOOD covering "Hot dogs" (inflected path),
// NYC covering "New York City" (exact path wins over the inflected duplicate)


AhoCorasickGlossaryMatcher matcher = new AhoCorasickGlossaryMatcher(
    List.of(new GlossaryEntry("Q1490", "東京")), false);

List<GlossaryMatch> hits = matcher.match("私は東京に住む");
// one hit whose span covers 東京 inside the unspaced sentence


TbxGlossaryReader reader = new TbxGlossaryReader("en");
List<GlossaryEntry> glossary;
try (InputStream in = Files.newInputStream(Path.of("terms.tbx"))) {
  glossary = reader.read(in);
}

AhoCorasickGlossaryMatcher matcher = new AhoCorasickGlossaryMatcher(glossary, true);
List<GlossaryMatch> hits = matcher.match("A frankfurter, please.");
// the hit reports the term's concept identifier


String csv = "id,term\nQ60,New York City\nQ11299,Manhattan\n";
CsvGlossaryReader reader = new CsvGlossaryReader(',', true);
List<GlossaryEntry> glossary = reader.read(
    new ByteArrayInputStream(csv.getBytes(StandardCharsets.UTF_8)));

AhoCorasickGlossaryMatcher matcher = new AhoCorasickGlossaryMatcher(glossary, true);
List<GlossaryMatch> hits = matcher.match("From Manhattan to New York City.");
// two hits: Q11299 and Q60

String csv = "id,term\nNY,\"New York, NY\"\nNY,NYC\n";
List<GlossaryEntry> glossary = new CsvGlossaryReader(',', true).read(
    new ByteArrayInputStream(csv.getBytes(StandardCharsets.UTF_8)));
AhoCorasickGlossaryMatcher matcher = new AhoCorasickGlossaryMatcher(glossary, true);
List<GlossaryMatch> hits = matcher.match("Visit New York, NY or NYC.");
// NY: "New York, NY" at [6..18), "NYC" at [22..25)

String tbx = """
    <tbx xmlns="urn:iso:std:iso:30042:ed-2">
      <text><body><conceptEntry id="NY">
        <langSec xml:lang="en"><termSec>
          <term>New <hi>York</hi></term>
          <note>Place name</note>
        </termSec></langSec>
      </conceptEntry></body></text>
    </tbx>
    """;
List<GlossaryEntry> glossary = new TbxGlossaryReader("en").read(
    new ByteArrayInputStream(tbx.getBytes(StandardCharsets.UTF_8)));
AhoCorasickGlossaryMatcher matcher = new AhoCorasickGlossaryMatcher(glossary, true);
List<GlossaryMatch> hits = matcher.match("From New York to Boston.");
// NY: "New York" at [5..13)

OffsetAwareNormalizer english = TextNormalizer.builder()
    .with(EnglishContractionCharSequenceNormalizer.getInstance())
    .buildAligned();

AlignedText expanded = english.normalizeAligned("we 'can't' leave");
// expanded.normalizedString() is "we 'can not' leave"
Span source = expanded.toOriginalSpan(4, 11);
// source is [4..9), covering "can't" in the original text
